from PIL import Image
import os
os.makedirs('views',exist_ok=True)
im=Image.open('translucent-reference.png')
print('png mode/info:', im.mode, im.info)
im=im.convert('RGBA'); w,h=im.size
S=12
def bg(color):
    return Image.new('RGBA',(w*S,h*S),color)
def checker():
    c=Image.new('RGBA',(w*S,h*S),(255,255,255,255)); p=c.load()
    for y in range(h*S):
        for x in range(w*S):
            if ((x//S)+(y//S))%2: p[x,y]=(200,200,200,255)
    return c
up=im.resize((w*S,h*S),Image.NEAREST)
for name,base in [('checker',checker()),('dark',bg((17,17,20,255))),('light',bg((238,238,232,255))),('mid-magenta',bg((200,60,180,255)))]:
    out=Image.alpha_composite(base,up); out.save(f'views/ref-{name}-12x.png')
im.resize((w*S,h*S),Image.NEAREST).save('views/ref-native-12x.png')
print('ok')
